const CALENDAR_DATE_MESSAGE = "Date must be in YYYY-MM-DD format";
export const calendarDate = z
	.string()
	.regex(/^\d{4}-\d{2}-\d{2}$/, CALENDAR_DATE_MESSAGE)
	.refine((value) => {
